-- 025_telecom_segments_rebuilds.sql
-- Telecom segments, part 2 of 3. GENERATED by server/src/db/gen/telecom-segments-sql.ts; do not edit.
-- Rebuilds the three tables whose UNIQUE constraint or table-level CHECKs must change: daily_closings (segment; one closing per
-- book + segment + day), cash_transfers (from_segment / to_segment; a transfer may also be between two different Telecom segments) and
-- sales (segment; client_ref unique per book + segment). Existing Telecom rows become 'legacy'; every other column value, id and the
-- AUTOINCREMENT counter are preserved exactly.
-- Same technique as 015 / 023: the runner executes this file in a transaction with foreign_keys ON, so each table is NOT renamed: its rows
-- are parked in a TEMP table, the table is dropped and re-created under its own name, and the rows are re-inserted with their ids (dropping
-- the parent counts the child rows as deferred violations; re-inserting the same ids clears them). Dropping a table also drops its indexes and
-- triggers, so EVERY index and trigger of each table is re-created (the text below is copied verbatim from a schema-23 database; the
-- closed-day triggers are replaced by their segment-aware versions in 026). The migration aborts (rolls back) if any row differs, a foreign key
-- is broken, or the set of indexes/triggers is not exactly the old set plus the new objects listed in the guard.

PRAGMA defer_foreign_keys = ON;

CREATE TEMP TABLE _mig025_objs AS
SELECT type, name, tbl_name FROM sqlite_master
 WHERE tbl_name IN ('daily_closings','cash_transfers','sales') AND type IN ('index','trigger') AND name NOT LIKE 'sqlite_autoindex%';

-- ===== daily_closings =====
CREATE TEMP TABLE _mig025_daily_closings AS SELECT id, book, business_date, posted_at, closed_at, reopened_at, reopen_reason, expected_cents, counted_cents, over_short_cents, cash_count_id FROM daily_closings;
CREATE TEMP TABLE _mig025_seq_daily_closings AS SELECT COALESCE((SELECT seq FROM sqlite_sequence WHERE name = 'daily_closings'), 0) AS seq;

DROP TABLE daily_closings;

CREATE TABLE daily_closings (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  book            TEXT    NOT NULL CHECK (book IN ('shop','telecom','icecream')),
  segment         TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy')),
  business_date   TEXT    NOT NULL,
  -- first closing time (server clock, never changes); closed_at = the latest close after any reopen
  posted_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  closed_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  reopened_at     TEXT,
  reopen_reason   TEXT,
  expected_cents  INTEGER NOT NULL,
  counted_cents   INTEGER CHECK (counted_cents IS NULL OR counted_cents >= 0),
  over_short_cents INTEGER NOT NULL DEFAULT 0,
  cash_count_id   INTEGER REFERENCES cash_counts(id),
  CHECK (business_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(business_date) IS NOT NULL AND date(business_date) = business_date),
  CHECK ((counted_cents IS NULL AND over_short_cents = 0)
      OR (counted_cents IS NOT NULL AND over_short_cents = counted_cents - expected_cents)),
  -- a reopen always records why (at least 3 characters)
  CHECK (reopened_at IS NULL OR (reopen_reason IS NOT NULL AND length(trim(reopen_reason)) >= 3)),
  -- the segment is named exactly for Telecom
  CHECK ((book = 'telecom') = (segment IS NOT NULL))
);

-- the triggers are re-created only after the copy, so none of them fires while the rows are copied back
INSERT INTO daily_closings (id, book, business_date, posted_at, closed_at, reopened_at, reopen_reason, expected_cents, counted_cents, over_short_cents, cash_count_id, segment)
SELECT id, book, business_date, posted_at, closed_at, reopened_at, reopen_reason, expected_cents, counted_cents, over_short_cents, cash_count_id, CASE WHEN book = 'telecom' THEN 'legacy' END FROM _mig025_daily_closings ORDER BY id;

UPDATE sqlite_sequence SET seq = max(seq, (SELECT seq FROM _mig025_seq_daily_closings)) WHERE name = 'daily_closings';

CREATE INDEX idx_daily_closings_business_date ON daily_closings(business_date);

CREATE INDEX idx_daily_closings_cash_count ON daily_closings(cash_count_id);

CREATE TRIGGER trg_daily_closings_future_date
BEFORE INSERT ON daily_closings
WHEN NEW.business_date > date('now','+330 minutes')
BEGIN
  SELECT RAISE(ABORT, 'FUTURE_DATE_NOT_ALLOWED');
END;

CREATE TRIGGER trg_daily_closings_immutable
BEFORE UPDATE ON daily_closings
WHEN NEW.id IS NOT OLD.id
  OR NEW.book IS NOT OLD.book
  OR NEW.business_date IS NOT OLD.business_date
  OR NEW.posted_at IS NOT OLD.posted_at
  OR NOT (
    ( (OLD.reopened_at IS NULL OR OLD.closed_at > OLD.reopened_at)
      AND NEW.reopened_at IS NOT NULL
      AND NEW.reopened_at >= OLD.closed_at
      AND NEW.closed_at IS OLD.closed_at
      AND NEW.expected_cents IS OLD.expected_cents
      AND NEW.counted_cents IS OLD.counted_cents
      AND NEW.over_short_cents IS OLD.over_short_cents
      AND NEW.cash_count_id IS OLD.cash_count_id )
    OR
    ( OLD.reopened_at IS NOT NULL AND OLD.closed_at <= OLD.reopened_at
      AND NEW.closed_at > OLD.reopened_at
      AND NEW.reopened_at IS OLD.reopened_at
      AND NEW.reopen_reason IS OLD.reopen_reason )
  )
BEGIN
  SELECT RAISE(ABORT, 'DAILY_CLOSING_IMMUTABLE');
END;

CREATE TRIGGER trg_daily_closings_no_delete
BEFORE DELETE ON daily_closings
BEGIN
  SELECT RAISE(ABORT, 'RECORD_DELETE_FORBIDDEN');
END;

-- one closing per scope and day (replaces UNIQUE (book, business_date); Shop / Ice Cream have segment NULL)
CREATE UNIQUE INDEX ux_daily_closings_scope_date ON daily_closings(book, COALESCE(segment, ''), business_date);
CREATE INDEX idx_daily_closings_book_date ON daily_closings(book, business_date);
-- the closed-day probe of every closed-day trigger: book = ? AND segment IS ? AND business_date >= ?
CREATE INDEX idx_daily_closings_book_segment_date ON daily_closings(book, segment, business_date);

CREATE TRIGGER trg_daily_closings_segment_insert
BEFORE INSERT ON daily_closings
WHEN (NEW.book = 'telecom') <> (NEW.segment IS NOT NULL) OR NEW.segment = 'legacy'
BEGIN
  SELECT RAISE(ABORT, CASE WHEN NEW.segment = 'legacy' THEN 'SEGMENT_LEGACY_REFUSED'
                           WHEN NEW.segment IS NULL THEN 'SEGMENT_REQUIRED' ELSE 'SEGMENT_NOT_ALLOWED' END);
END;

CREATE TRIGGER trg_daily_closings_segment_immutable
BEFORE UPDATE OF segment ON daily_closings
WHEN NEW.segment IS NOT OLD.segment
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_READ_ONLY');
END;

-- ===== cash_transfers =====
CREATE TEMP TABLE _mig025_cash_transfers AS SELECT id, business_date, posted_at, from_book, to_book, from_fund, to_fund, amount_cents, note, status, voided_at, void_reason, client_ref FROM cash_transfers;
CREATE TEMP TABLE _mig025_seq_cash_transfers AS SELECT COALESCE((SELECT seq FROM sqlite_sequence WHERE name = 'cash_transfers'), 0) AS seq;

DROP TABLE cash_transfers;

CREATE TABLE cash_transfers (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  business_date TEXT    NOT NULL,
  posted_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  from_book     TEXT    NOT NULL CHECK (from_book IN ('shop','telecom','icecream')),
  to_book       TEXT    NOT NULL CHECK (to_book IN ('shop','telecom','icecream')),
  from_fund     TEXT    CHECK (from_fund IS NULL OR from_fund IN ('cost','electricity','profit')),
  to_fund       TEXT    CHECK (to_fund IS NULL OR to_fund IN ('cost','electricity','profit')),
  amount_cents  INTEGER NOT NULL CHECK (amount_cents BETWEEN 1 AND 1000000000000),
  note          TEXT    NOT NULL DEFAULT '',
  status        TEXT    NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','void')),
  voided_at     TEXT,
  void_reason   TEXT,
  client_ref    TEXT    NOT NULL UNIQUE,
  from_segment  TEXT CHECK (from_segment IS NULL OR from_segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy')),
  to_segment    TEXT CHECK (to_segment IS NULL OR to_segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy')),
  CHECK (business_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(business_date) IS NOT NULL AND date(business_date) = business_date),
  -- section 8: money moves BETWEEN two different books; section 13D: or between two different Telecom segments
  CHECK (from_book <> to_book OR (from_book = 'telecom' AND from_segment <> to_segment)),
  -- section 10.2: the fund is named exactly on the Ice Cream side(s)
  CHECK ((from_book = 'icecream') = (from_fund IS NOT NULL)),
  CHECK ((to_book = 'icecream') = (to_fund IS NOT NULL)),
  -- section 13D: the segment is named exactly on the Telecom side(s)
  CHECK ((from_book = 'telecom') = (from_segment IS NOT NULL)),
  CHECK ((to_book = 'telecom') = (to_segment IS NOT NULL)),
  CHECK (status = 'posted' OR (voided_at IS NOT NULL AND void_reason IS NOT NULL)),
  CHECK (status = 'void' OR (voided_at IS NULL AND void_reason IS NULL))
);

-- the triggers are re-created only after the copy, so none of them fires while the rows are copied back
INSERT INTO cash_transfers (id, business_date, posted_at, from_book, to_book, from_fund, to_fund, amount_cents, note, status, voided_at, void_reason, client_ref, from_segment, to_segment)
SELECT id, business_date, posted_at, from_book, to_book, from_fund, to_fund, amount_cents, note, status, voided_at, void_reason, client_ref, CASE WHEN from_book = 'telecom' THEN 'legacy' END, CASE WHEN to_book = 'telecom' THEN 'legacy' END FROM _mig025_cash_transfers ORDER BY id;

UPDATE sqlite_sequence SET seq = max(seq, (SELECT seq FROM _mig025_seq_cash_transfers)) WHERE name = 'cash_transfers';

CREATE INDEX idx_cash_transfers_business_date ON cash_transfers(business_date);

CREATE INDEX idx_cash_transfers_from ON cash_transfers(from_book, business_date);

CREATE INDEX idx_cash_transfers_posted_at ON cash_transfers(posted_at);

CREATE INDEX idx_cash_transfers_to ON cash_transfers(to_book, business_date);

CREATE TRIGGER trg_cash_transfers_business_date_immutable
BEFORE UPDATE OF business_date ON cash_transfers
WHEN NEW.business_date <> OLD.business_date
BEGIN
  SELECT RAISE(ABORT, 'BUSINESS_DATE_IMMUTABLE');
END;

CREATE TRIGGER trg_cash_transfers_day_closed
BEFORE INSERT ON cash_transfers
WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book IN (NEW.from_book, NEW.to_book) AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book IN (NEW.from_book, NEW.to_book) AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

CREATE TRIGGER trg_cash_transfers_day_closed_void
BEFORE UPDATE OF status ON cash_transfers
WHEN OLD.status = 'posted' AND NEW.status = 'void'
  AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book IN (OLD.from_book, OLD.to_book) AND d.business_date >= OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book IN (OLD.from_book, OLD.to_book) AND d.business_date = OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

CREATE TRIGGER trg_cash_transfers_future_date
BEFORE INSERT ON cash_transfers
WHEN NEW.business_date > date('now','+330 minutes')
BEGIN
  SELECT RAISE(ABORT, 'FUTURE_DATE_NOT_ALLOWED');
END;

CREATE TRIGGER trg_cash_transfers_immutable
BEFORE UPDATE OF id, from_book, to_book, from_fund, to_fund, amount_cents, note, client_ref, status, voided_at, void_reason ON cash_transfers
WHEN NEW.id IS NOT OLD.id
  OR NEW.from_book IS NOT OLD.from_book
  OR NEW.to_book IS NOT OLD.to_book
  OR NEW.from_fund IS NOT OLD.from_fund
  OR NEW.to_fund IS NOT OLD.to_fund
  OR NEW.amount_cents IS NOT OLD.amount_cents
  OR NEW.note IS NOT OLD.note
  OR NEW.client_ref IS NOT OLD.client_ref
  OR (OLD.status = 'void' AND (NEW.status IS NOT OLD.status
        OR NEW.voided_at IS NOT OLD.voided_at OR NEW.void_reason IS NOT OLD.void_reason))
  OR (OLD.status = 'posted' AND NEW.status = 'posted'
        AND (NEW.voided_at IS NOT OLD.voided_at OR NEW.void_reason IS NOT OLD.void_reason))
BEGIN
  SELECT RAISE(ABORT, 'CASH_TRANSFER_IMMUTABLE');
END;

CREATE TRIGGER trg_cash_transfers_no_delete
BEFORE DELETE ON cash_transfers
BEGIN
  SELECT RAISE(ABORT, 'RECORD_DELETE_FORBIDDEN');
END;

CREATE TRIGGER trg_cash_transfers_posted_at_immutable
BEFORE UPDATE OF posted_at ON cash_transfers
WHEN NEW.posted_at IS NOT OLD.posted_at
BEGIN
  SELECT RAISE(ABORT, 'POSTED_AT_IMMUTABLE');
END;

CREATE TRIGGER trg_cash_transfers_void_requires_reversal
BEFORE UPDATE OF status ON cash_transfers
WHEN OLD.status <> 'void' AND NEW.status = 'void' AND NEW.voided_at IS NOT NULL AND NEW.void_reason IS NOT NULL
 AND (
    EXISTS (SELECT 1 FROM cash_entries o
             WHERE o.ref_table = 'cash_transfers' AND o.ref_id = OLD.id AND o.reverses_entry_id IS NULL AND o.amount_cents <> 0
               AND NOT EXISTS (SELECT 1 FROM cash_entries r
                                WHERE r.reverses_entry_id = o.id AND r.amount_cents = -o.amount_cents AND r.book = o.book
                                  AND r.fund IS o.fund AND r.business_date = o.business_date))
    OR EXISTS (SELECT 1 FROM stock_movements o
                WHERE o.ref_table = 'cash_transfers' AND o.ref_id = OLD.id AND o.reverses_movement_id IS NULL
                  AND NOT EXISTS (SELECT 1 FROM stock_movements r WHERE r.reverses_movement_id = o.id)
                  AND NOT (o.type = 'adjustment' AND o.qty_delta = 0 AND o.value_delta_cents < 0
                           AND EXISTS (SELECT 1 FROM stock_movements c
                                        WHERE c.ref_table = o.ref_table AND c.ref_id = o.ref_id AND c.product_id = o.product_id
                                          AND c.reverses_movement_id IS NOT NULL AND c.id > o.id)))
    OR EXISTS (SELECT 1 FROM icecream_fund_entries o
                WHERE o.ref_table = 'cash_transfers' AND o.ref_id = OLD.id AND o.reverses_entry_id IS NULL
                  AND NOT EXISTS (SELECT 1 FROM icecream_fund_entries r
                                   WHERE r.reverses_entry_id = o.id AND r.amount_cents = -o.amount_cents AND r.fund = o.fund
                                     AND r.business_date = o.business_date))
 )
BEGIN
  SELECT RAISE(ABORT, 'VOID_WITHOUT_REVERSAL');
END;

CREATE TRIGGER trg_cash_transfers_segment_insert
BEFORE INSERT ON cash_transfers
WHEN (NEW.from_book = 'telecom') <> (NEW.from_segment IS NOT NULL) OR (NEW.to_book = 'telecom') <> (NEW.to_segment IS NOT NULL)
  OR NEW.from_segment = 'legacy' OR NEW.to_segment = 'legacy'
BEGIN
  SELECT RAISE(ABORT, CASE WHEN NEW.from_segment = 'legacy' OR NEW.to_segment = 'legacy' THEN 'SEGMENT_LEGACY_REFUSED'
                           WHEN (NEW.from_book = 'telecom' AND NEW.from_segment IS NULL) OR (NEW.to_book = 'telecom' AND NEW.to_segment IS NULL)
                           THEN 'SEGMENT_REQUIRED' ELSE 'SEGMENT_NOT_ALLOWED' END);
END;

CREATE TRIGGER trg_cash_transfers_segment_immutable
BEFORE UPDATE OF from_segment, to_segment ON cash_transfers
WHEN NEW.from_segment IS NOT OLD.from_segment OR NEW.to_segment IS NOT OLD.to_segment
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_READ_ONLY');
END;

-- a transfer leg must carry the segment of its side of the transfer (same predicate as before plus the segment)
DROP TRIGGER trg_cash_entries_transfer_link;
CREATE TRIGGER trg_cash_entries_transfer_link
BEFORE INSERT ON cash_entries
WHEN NEW.type IN ('transfer_out','transfer_in') OR NEW.transfer_id IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'TRANSFER_LEG_MISMATCH')
   WHERE NEW.transfer_id IS NULL
      OR NEW.type NOT IN ('transfer_out','transfer_in')
      OR NOT EXISTS (
        SELECT 1 FROM cash_transfers t
         WHERE t.id = NEW.transfer_id
           AND ((NEW.type = 'transfer_out' AND t.from_book = NEW.book AND t.from_fund IS NEW.fund AND t.from_segment IS NEW.segment)
             OR (NEW.type = 'transfer_in'  AND t.to_book   = NEW.book AND t.to_fund   IS NEW.fund AND t.to_segment   IS NEW.segment))
      );
END;

-- ===== sales =====
CREATE TEMP TABLE _mig025_sales AS SELECT id, business_date, posted_at, book, total_cents, status, notes, client_ref, voided_at, void_reason FROM sales;
CREATE TEMP TABLE _mig025_seq_sales AS SELECT COALESCE((SELECT seq FROM sqlite_sequence WHERE name = 'sales'), 0) AS seq;

DROP TABLE sales;

CREATE TABLE sales (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  business_date  TEXT    NOT NULL,
  posted_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  book           TEXT    NOT NULL CHECK (book IN ('shop','telecom')),
  segment        TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'mobitel_cards', 'airtel_cards', 'hutch_cards', 'legacy')),
  total_cents    INTEGER NOT NULL CHECK (total_cents >= 0),
  status         TEXT    NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','void')),
  notes          TEXT    NOT NULL DEFAULT '',
  client_ref     TEXT    NOT NULL,
  voided_at      TEXT,
  void_reason    TEXT,
  -- real calendar date only (GLOB checks the shape, date() rejects 31 February)
  CHECK (business_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(business_date) = business_date),
  -- a void always records when and why
  CHECK (status = 'posted' OR (voided_at IS NOT NULL AND void_reason IS NOT NULL)),
  -- the segment is named exactly for Telecom
  CHECK ((book = 'telecom') = (segment IS NOT NULL))
);

-- the triggers are re-created only after the copy, so none of them fires while the rows are copied back
INSERT INTO sales (id, business_date, posted_at, book, total_cents, status, notes, client_ref, voided_at, void_reason, segment)
SELECT id, business_date, posted_at, book, total_cents, status, notes, client_ref, voided_at, void_reason, CASE WHEN book = 'telecom' THEN 'legacy' END FROM _mig025_sales ORDER BY id;

UPDATE sqlite_sequence SET seq = max(seq, (SELECT seq FROM _mig025_seq_sales)) WHERE name = 'sales';

CREATE INDEX idx_sales_book_business_date ON sales(book, business_date);

CREATE INDEX idx_sales_business_date ON sales(business_date);

CREATE TRIGGER trg_sales_business_date_immutable
BEFORE UPDATE OF business_date ON sales
WHEN NEW.business_date <> OLD.business_date
BEGIN
