CREATE TEMP TABLE _mig025_guard (ok INTEGER NOT NULL CHECK (ok = 1));
INSERT INTO _mig025_guard SELECT CASE WHEN
  (SELECT COUNT(*) FROM daily_closings) = (SELECT COUNT(*) FROM _mig025_daily_closings)
 AND   NOT EXISTS (SELECT 1 FROM _mig025_daily_closings o LEFT JOIN daily_closings n ON n.id = o.id WHERE n.id IS NULL OR n.id IS NOT o.id
                      OR n.book IS NOT o.book
                      OR n.business_date IS NOT o.business_date
                      OR n.posted_at IS NOT o.posted_at
                      OR n.closed_at IS NOT o.closed_at
                      OR n.reopened_at IS NOT o.reopened_at
                      OR n.reopen_reason IS NOT o.reopen_reason
                      OR n.expected_cents IS NOT o.expected_cents
                      OR n.counted_cents IS NOT o.counted_cents
                      OR n.over_short_cents IS NOT o.over_short_cents
                      OR n.cash_count_id IS NOT o.cash_count_id
                      OR n.segment IS NOT (CASE WHEN o.book = 'telecom' THEN 'legacy' END))
 AND   (SELECT COUNT(*) FROM cash_transfers) = (SELECT COUNT(*) FROM _mig025_cash_transfers)
 AND   NOT EXISTS (SELECT 1 FROM _mig025_cash_transfers o LEFT JOIN cash_transfers n ON n.id = o.id WHERE n.id IS NULL OR n.id IS NOT o.id
                      OR n.business_date IS NOT o.business_date
                      OR n.posted_at IS NOT o.posted_at
                      OR n.from_book IS NOT o.from_book
                      OR n.to_book IS NOT o.to_book
                      OR n.from_fund IS NOT o.from_fund
                      OR n.to_fund IS NOT o.to_fund
                      OR n.amount_cents IS NOT o.amount_cents
                      OR n.note IS NOT o.note
                      OR n.status IS NOT o.status
                      OR n.voided_at IS NOT o.voided_at
                      OR n.void_reason IS NOT o.void_reason
                      OR n.client_ref IS NOT o.client_ref
                      OR n.from_segment IS NOT (CASE WHEN o.from_book = 'telecom' THEN 'legacy' END)
                      OR n.to_segment IS NOT (CASE WHEN o.to_book = 'telecom' THEN 'legacy' END))
 AND   (SELECT COUNT(*) FROM sales) = (SELECT COUNT(*) FROM _mig025_sales)
 AND   NOT EXISTS (SELECT 1 FROM _mig025_sales o LEFT JOIN sales n ON n.id = o.id WHERE n.id IS NULL OR n.id IS NOT o.id
                      OR n.business_date IS NOT o.business_date
                      OR n.posted_at IS NOT o.posted_at
                      OR n.book IS NOT o.book
                      OR n.total_cents IS NOT o.total_cents
                      OR n.status IS NOT o.status
                      OR n.notes IS NOT o.notes
                      OR n.client_ref IS NOT o.client_ref
                      OR n.voided_at IS NOT o.voided_at
                      OR n.void_reason IS NOT o.void_reason
                      OR n.segment IS NOT (CASE WHEN o.book = 'telecom' THEN 'legacy' END))
 AND   NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check)
 AND   NOT EXISTS (SELECT 1 FROM _mig025_objs o WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = o.type AND m.name = o.name AND m.tbl_name = o.tbl_name))
 AND   NOT EXISTS (SELECT 1 FROM _mig025_new w WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.name = w.name))
 AND   (SELECT COUNT(*) FROM sqlite_master WHERE tbl_name IN ('daily_closings','cash_transfers','sales') AND type IN ('index','trigger') AND name NOT LIKE 'sqlite_autoindex%') = (SELECT COUNT(*) FROM _mig025_objs) + (SELECT COUNT(*) FROM _mig025_new)
  THEN 1 ELSE 0 END;

